"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77137"],{99573(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modalidade.cota_sem_opcao_pelas_cotas_da_lei","status":422,"titulo":"A cota da lei exige a op\xe7\xe3o pelas cotas em toda alternativa da regra"},"descricao":{"codigo":"uniplus.configuracao.modalidade.cota_sem_opcao_pelas_cotas_da_lei","requisitos":["UNI-REQ-0076","UNI-REQ-0142"],"oQueAconteceu":["Uma alternativa da regra de aplicabilidade da cota reservada n\xe3o exige que o candidato tenha optado pelas cotas da Lei 12.711. Uma regra sem alternativas tamb\xe9m \xe9 recusada, pois deixaria a cota aberta a todo candidato. Nada foi gravado.","Na atualiza\xe7\xe3o, a modalidade \xe9 procurada antes desta confer\xeancia: com um identificador inexistente a resposta \xe9 [modalidade n\xe3o encontrada](/erros/uniplus.configuracao.modalidade.nao_encontrada), mesmo que o conte\xfado enviado tamb\xe9m tivesse este problema. Numa modalidade do cat\xe1logo legal fixo esta recusa n\xe3o \xe9 emitida: se o conte\xfado altera algo al\xe9m da descri\xe7\xe3o e da base legal, vale [estrutura protegida n\xe3o edit\xe1vel](/erros/uniplus.configuracao.modalidade.estrutura_protegida_nao_editavel)."],"comoResolver":["Inclua, em cada alternativa da regra, a condi\xe7\xe3o de que o candidato optou pelas cotas da Lei 12.711, junto das demais condi\xe7\xf5es que definem o grupo da cota (renda, origem escolar, ra\xe7a ou etnia, defici\xeancia)."],"ondeAparece":["Cria\xe7\xe3o de uma modalidade (POST /api/configuracao/admin/modalidades)","Atualiza\xe7\xe3o de uma modalidade fora do cat\xe1logo legal fixo (PUT /api/configuracao/admin/modalidades/`{id}`), depois de a modalidade ser encontrada"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modalidade"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"418da40321f5e48caae8956b248f9336904d661a"}}')}}]);